mapper.select:
SELECT 
  FROM sys14_holiday
 WHERE sys14_company_id = #{companyId}
   AND to_char(sys14_day,'yyyy') LIKE #{year}
 ORDER BY sys14_day

mapper.update:
UPDATE sys14_holiday
   SET sys14_day        = #{req.day}::timestamp,
       sys14_holiday_nm = #{req.holidayName},
       sys14_note       = #{req.note}
 WHERE sys14_holiday_id = #{req.holidayId}
   AND sys14_company_id = #{companyId}

mapper.delete:
DELETE FROM sys14_holiday
 WHERE sys14_company_id = #{companyId}
   AND sys14_holiday_id IN
#{id}

DELETE FROM sys14_holiday
 WHERE sys14_company_id = #{companyId}
   AND sys14_day        = #{day}::timestamp
